import React, { useCallback, useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useQueryClient } from 'react-query';
import { getOrgList } from 'redux/actions/common';
import ProfileImageOrText from 'components/features/setting/ProfileImageOrText';
import AppAddModalForm from 'components/features/setting/OrganizationSetting/AppSection/AppAddModalForm';
import { trackPageViews } from 'redux/actions/trackingReport';
import RightSideSVG from 'public/static/redesign/sidebar/right_expand.svg';
import ContentInformation from './ContentInformation';
import { OrganizationSettingWrap } from '../Sidebar/menuBar/styles';
import CommonPopover from '../NewAppMenu/CommonPopover';

const NewOrganizationSetting = (props) => {
  const dispatch = useDispatch();
  const {
    collapsed,
    logout,
    navigateToTeam,
    navigateToSubscription,
    urlRouteTo,
    planhatPortalLink,
    planHatPortalAccessData
  } = props;

  const {
    profileReducer: user,
    urlReducer: { parentType },
  } = useSelector((state) => state);

  const [visible, setVisible] = useState(false);
  const [imgSrc, setImgSrc] = useState();
  const [visibleCreateAppModal, setVisibleCreateAppModal] = useState(false);
  const [selectedOrgId, setSelectedOrgId] = useState();
  const queryClient = useQueryClient();

  const handleVisibleChange = (value) => setVisible(value);
 const profileQueryKey = 'profileInfo'

  useEffect(() => {
    dispatch(getOrgList());
  }, []);

  useEffect(() => {
    user?.profilePicture && setImgSrc(user?.profilePicture);
  }, [user?.profilePicture]);

  useEffect(()=>{
    queryClient.setQueryData(profileQueryKey, user)
  }, [user, queryClient])

  const handleLogOut = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    dispatch(
      trackPageViews(null, {
        eventName: 'wa_log_out',
      })
    );
    logout();
  }, [dispatch, logout]);

  return (
    <>
      <CommonPopover
        placement="rightBottom"
        collapsed={collapsed}
        content={
          <ContentInformation
            logout={handleLogOut}
            // handleNavigateToProfile={handleNavigateToProfile}
            navigateToTeam={navigateToTeam}
            navigateToSubscription={navigateToSubscription}
            urlRouteTo={urlRouteTo}
            handleVisibleChange={handleVisibleChange}
            planhatPortalLink={planhatPortalLink}
            planHatPortalAccessData={planHatPortalAccessData}
            setVisibleCreateAppModal={setVisibleCreateAppModal}
            setSelectedOrgId={setSelectedOrgId}
          />
        }
        trigger={collapsed ? 'hover' : 'click'}
        mouseEnterDelay={collapsed ? 0.4 : undefined}
        visible={visible}
        onVisibleChange={handleVisibleChange}
      >
        <OrganizationSettingWrap className={parentType === 'settings' ? 'selected' : ''}>
          <ProfileImageOrText
            className="avatar-box"
            size={24}
            picture={imgSrc}
            shape="circle"
            nameInfo={user?.name ? user?.name?.trim() : user?.email?.trim()}
          />
          {
            !collapsed && (
              <span className="user-name-pop" id="profile-name">
                {user?.name}
              </span>
            )
          }
          <RightSideSVG />
        </OrganizationSettingWrap>
      </CommonPopover>
      {visibleCreateAppModal && (
        <AppAddModalForm
          visibleCreateAppModal={visibleCreateAppModal}
          organizationId={selectedOrgId}
        />
      )}
    </>

  );
};

export default NewOrganizationSetting;
