const SubscriptionView = ['subscription.view', 'subscription.update'];

export const CommonInfoBox = ({
  value,
  memberCount,
  uniqueKey,
  listView,
  isActive,
  orgId,
  handleVisibleChange,
  validatePermission,
}) => {
  const parentRef = useRef();
  return (
    <FlexDiv listView={listView} key={uniqueKey}>
      <ProfileInfo>
        <NameDiv>
          <strong>
            <ProfileImageOrText
              className="avatar-box"
              size={32}
              picture={value?.image}
              shape="circle"
              nameInfo={
                value?.name ? value?.name?.trim() : value?.email?.trim()
              }
            />
          </strong>
          <AppName ref={parentRef} active={isActive} isOwner={value?.isOwner && isActive}>
            {(isActive || !listView) &&
            validatePermission(['organization.update', 'organization.view']) ? (
              <Link
                href={{
                  pathname: '/integration',
                  query: {
                    parentType: 'settings',
                    setting: 'org_setting',
                    org_tab: 'profile',
                    orgId,
                    org: orgId,
                  },
                }}
                as={`/settings/org/${orgId}/profile`}
                passHref
              >
                <LinkButton
                  isactive={isActive ? 1 : 0}
                  // onClick={() => handleVisibleChange(false)}
                  type="link"
                >
                  <OrgNameDiv>
                    <TextTruncated width={ 186 } value={value?.name} />
                  </OrgNameDiv>
                </LinkButton>
              </Link>
            ) : (
              <TextTruncated width={ 186 } value={value?.name} />
            )}

            {memberCount && (
              <p> {`${memberCount} member${memberCount > 1 ? 's' : ''}`}</p>
            )}
          </AppName>
        </NameDiv>
        {value?.isOwner && isActive && <OwnerDiv>Owner</OwnerDiv>}
      </ProfileInfo>
    </FlexDiv>
  );
};

const ContentInformation = ({
  logout,
  navigateToTeam,
  urlRouteTo,
  navigateToSubscription,
  handleVisibleChange,
  planhatPortalLink,
  planHatPortalAccessData,
  setVisibleCreateAppModal,
  setSelectedOrgId,
}) => {
  const dispatch = useDispatch();
  const {
    organizationReducer: organizationList,
    currentOrgReducer: activeSubscription,
    applicationReducer: orgList,
    urlReducer: urlQuery,
    profileReducer: profile,
  } = useSelector((state) => state);
  const queryClient = useQueryClient();

  const { data: definedRoles } = useFetchRolesAndPermission('roles_permission');

  const handleUpdateProfile = useCallback((profileData) => {
    queryClient.setQueryData(`profileInfo`, profileData);
  },[queryClient]);

  const currentOrg = useMemo(
    () =>
      organizationList?.length > 0
        ? organizationList?.find(
            ({ _id: orgId }) => orgId === activeSubscription?.orgId
          )
        : {},
    [organizationList, activeSubscription]
  );

  const validatePermission = useCallback(
    (permissionCode) =>
      profile &&
      authorizeOrgManagerPermission(
        permissionCode,
        definedRoles,
        profile?.organization,
        activeSubscription?.orgId
      ),
    [profile, definedRoles, activeSubscription?.orgId]
  );

  useEffect(() => {
    profile && handleUpdateProfile(profile);
  }, [profile, handleUpdateProfile]);

  return (
    <MainDiv data-intercom-target="User Info">
      <MultipleOrg isMultiple={organizationList?.length}>
        {organizationList?.length > 1 && (
          <StyledTitle>My organizations</StyledTitle>
        )}
        <MyOrganization isactive={organizationList?.length > 1}>
          <CommonInfoBox
            value={currentOrg}
            memberCount={currentOrg?.totalMembers}
            uniqueKey="has_multiple"
            isActive={organizationList?.length > 1}
            orgId={activeSubscription?.orgId}
            handleVisibleChange={handleVisibleChange}
            validatePermission={validatePermission}
          />
          <Subscription isMultiple={organizationList?.length}>
            {validatePermission(SubscriptionView) && (
              <StyledButton
                onClick={() => {
                  navigateToSubscription();
                  handleVisibleChange(false);
                }}
                data-intercom-target="User Subscription"
              >
                Subscription
              </StyledButton>
            )}

            <StyledButton
              onClick={() => {
                navigateToTeam();
                handleVisibleChange(false);
              }}
              data-intercom-target="User Team"
            >
              Team
            </StyledButton>
          </Subscription>
        </MyOrganization>
        {organizationList?.length > 1 &&
          organizationList.map((org) => {
            const { _id: orgId } = org;
            if (orgId !== activeSubscription?.orgId) {
              const remainingOrg = orgList?.filter(
                (orgValue) => orgValue?.orgId === orgId
              );
              const orgInfo =
                remainingOrg && remainingOrg?.length ? remainingOrg[0] : {};
              if (orgInfo?.apps?.length === 0) {
                return (
                    <ul
                      aria-hidden
                      key={orgId}
                      onClick={() => {
                        try {
                          localStorage.setItem('orgId', orgId);
                        } catch (err) {
                          // silent fail
                        }
                      }}
                      style={{ cursor: 'pointer' }}
                    >
                      <div
                        aria-hidden
                        onClick={() => {
                          setSelectedOrgId(orgId);
                          setVisibleCreateAppModal(true);
                          handleVisibleChange(false);
                        }}
                      >
                        <CommonInfoBox
                          value={org}
                          memberCount={org?.totalMembers}
                          uniqueKey={orgId}
                          listView
                          validatePermission={validatePermission}
                        />
                      </div>
                    </ul>
                );
              }
              if (orgInfo?.apps?.length > 0) {
                const indexAppid = findLastIndex(orgInfo.apps, {
                  isLastVisitedApp: true,
                });

                const appId =
                  indexAppid > -1 && orgInfo?.apps[indexAppid]?.hasAccess
                    ? orgInfo?.apps?.[indexAppid]['_id']
                    : orgInfo?.apps?.[0]['_id'];
                const isIntegrated =
                  indexAppid > -1
                    ? orgInfo.apps[indexAppid].isIntegrated
                    : orgInfo.apps[0].isIntegrated;

                const currentParentType = urlQuery.parentType;
                const queryPType =
                  !currentParentType ||
                  currentParentType === 'settings' ||
                  currentParentType === 'integration' ||
                  currentParentType === 'dashboard' ||
                  currentParentType === 'plan-downgrade'
                    ? 'overview'
                    : currentParentType;

                const currentQuery = {
                  appId,
                  orgId,
                  org: orgId,
                  parentType: isIntegrated ? queryPType : 'integration',
                  ...(currentParentType === 'eventsList' && { eventpage:  1}),
                  ...(currentParentType === 'issues' && { issueType:  'crashes'})
                };
                
                const asHref = isIntegrated
                  ? `/app/${appId}/${urlRouteTo}`
                  : `/integration?appId=${appId}`;

                return (
                  <ul
                    aria-hidden
                    key={orgId}
                    onClick={() => {
                      try {
                        localStorage.setItem('orgId', orgId);
                        localStorage.setItem('appId', appId);
                      } catch (err) {
                        // silent fail
                      }
                      dispatch(lastAppSelected(appId));
                      dispatch(resetFilterV2());
                      dispatch(checkPlanStatus(orgId))
                        .then((res) => {
                          const isPlanActionNeeded =
                            res?.selectAppAction || res?.selectUserAction;
                          if (!isPlanActionNeeded) {
                            Router.push(
                              { pathname: '/integration', query: currentQuery },
                              asHref
                            )
                          } else {
                            Router.push(
                              `/integration?parentType=plan-downgrade&appId=${
                                appId || ''
                              }${orgId ? `&orgId=${orgId}` : ''}`,
                              `/plan-downgrade?appId=${appId || ''}${
                                orgId ? `&orgId=${orgId}` : ''
                              }`
                            )
                          }
                        })
                        .catch(() => {
                          Router.push(
                            {
                              pathname: '/integration',
                              query: currentQuery,
                              asPath: asHref,
                            },
                            asHref
                          )
                        });
                      handleVisibleChange(false);
                    }}
                    style={{ cursor: 'pointer' }}
                  >
                    <div
                      aria-hidden
                    >
                      <CommonInfoBox
                        value={org}
                        memberCount={org?.totalMembers}
                        uniqueKey={orgId}
                        listView
                        validatePermission={validatePermission}
                      />
                    </div>
                  </ul>
                );
              }
            }
          })}
      </MultipleOrg>

      <ProfileDiv>
        <Link
          href={{
            pathname: '/integration',
            query: {
              parentType: 'settings',
              setting: 'profile_setting',
              orgId: activeSubscription?.orgId,
              org: activeSubscription?.orgId,
            },
          }}
          as="/settings/profile"
          passHref
        >
          <ListMenu onClick={() => handleVisibleChange(false)}>
            <ProfileIcon />
            My profile
          </ListMenu>
        </Link>
        {planHatPortalAccessData?.accessToSharedView && (
          <ListMenu onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            planhatPortalLink(planHatPortalAccessData?.endUserId);
          }}>
            <PortalLinkSvg />
            My portal
          </ListMenu>
        )}

        <ListMenu onClick={(e) => logout(e)}>
          <SignoutIcon />
          Sign out
        </ListMenu>
      </ProfileDiv>
    </MainDiv>
  );
};

export default ContentInformation;
